import { esc, icon, brand } from './views.js?v=cf0edce1d5';
import { money, messages } from './i18n.js?v=cf0edce1d5';
import { copy } from './catalog.js?v=cf0edce1d5';
import { previews } from './previews.js?v=cf0edce1d5';
import { DEMO_ACCOUNTS, DEMO_PASSWORD, ROLES, LEARNERS, TEMPLATE_COURSES, learnerIds, courseIds, metrics, progress, visibleResources, messageRecipients, quizForCourse } from './school-core.js?v=cf0edce1d5';

export const NAV={
 admin:[['overview','Vue d’ensemble','chart'],['people','Comptes & inscriptions','nodes'],['courses','Formations','book'],['resources','Bibliothèque','download'],['assignments','Devoirs & corrections','code'],['attendance','Présences','check'],['calendar','Planning','clock'],['finance','Finances démo','cart'],['messages','Messagerie démo','mail'],['content','Vitrine & annonces','web'],['settings','Sauvegarde & journal','lock']],
 teacher:[['overview','Vue d’ensemble','chart'],['courses','Mes groupes','book'],['assignments','Devoirs & corrections','code'],['attendance','Présences','check'],['resources','Bibliothèque','download'],['calendar','Planning','clock'],['messages','Messagerie démo','mail']],
 student:[['overview','Mon tableau de bord','chart'],['courses','Mes formations','book'],['assignments','Mes devoirs','code'],['resources','Mes ressources','download'],['calendar','Mon agenda','clock'],['finance','Mes échéances démo','cart'],['messages','Messagerie démo','mail']],
 lycee:[['overview','Mon tableau de bord','chart'],['courses','Mes matières','book'],['assignments','Mes devoirs','code'],['resources','Mes ressources','download'],['calendar','Mon agenda','clock'],['finance','Mes échéances démo','cart'],['messages','Messagerie démo','mail']],
 professional:[['overview','Mon tableau de bord','chart'],['courses','Mes formations','book'],['assignments','Mes projets','code'],['resources','Mes ressources','download'],['calendar','Mon agenda','clock'],['finance','Mes échéances démo','cart'],['messages','Messagerie démo','mail']],
 parent:[['overview','Vue d’ensemble','chart'],['followup','Progression & bulletins','book'],['assignments','Devoirs & retours','code'],['attendance','Présences','check'],['resources','Ressources des enfants','download'],['calendar','Agenda familial','clock'],['finance','Échéances démo','cart'],['messages','Messagerie démo','mail']]
};
export const labels={present:'Présent',absent:'Absent',late:'Retard',excused:'Absence justifiée'};
export const dateLabel=(value,time=false)=>new Intl.DateTimeFormat('fr-FR',{timeZone:'Africa/Algiers',day:'numeric',month:'short',...(time?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(value));
const name=(s,id)=>s.users.find(u=>u.id===id)?.name||'Compte supprimé';
const courseName=(s,id)=>copy(s.courses.find(c=>c.id===id)?.title)||'Formation';
const button=(label,action,id='',style='secondary')=>`<button class="school-button ${style}" data-school-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`;
const empty=(title,text)=>`<div class="school-empty">${icon('book')}<h3>${esc(title)}</h3><p>${esc(text)}</p></div>`;
const badge=(label,style='')=>`<span class="school-badge ${style}">${esc(label)}</span>`;
const field=(label,input,full=false)=>`<label class="school-field ${full?'full':''}"><span>${label}</span>${input}</label>`;
const input=(key,value='',type='text',extra='')=>`<input name="${key}" type="${type}" value="${esc(value)}" ${extra}>`;
const textarea=(key,value='',rows=4,extra='')=>`<textarea name="${key}" rows="${rows}" ${extra}>${esc(value)}</textarea>`;
const options=(items,selected)=>items.map(([id,label])=>`<option value="${esc(id)}" ${id===selected?'selected':''}>${esc(label)}</option>`).join('');
const select=(key,items,selected='',extra='')=>`<select name="${key}" ${extra}>${options(items,selected)}</select>`;
const saveButton=label=>`<button class="school-button primary" type="submit">${esc(label)}${icon('arrow')}</button><p class="school-form-status" role="status" aria-live="polite"></p>`;
const moduleBar=(value)=>`<div class="school-progress" role="progressbar" aria-label="Modules parcourus en démonstration" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value}"><span style="width:${value}%"></span></div>`;
const findCourse=(s,id)=>s.courses.find(c=>c.id===id);
const matches=(value,q)=>!q||String(value).toLocaleLowerCase('fr').includes(q.toLocaleLowerCase('fr'));
const panelHeading=(title,copy,action='')=>`<div class="school-section-title"><div><h2>${esc(title)}</h2><p>${esc(copy)}</p></div>${action}</div>`;
const search=(query,placeholder)=>`<form data-school-form="search" class="school-search"><label><span class="sr-only">${esc(placeholder)}</span><input name="query" type="search" value="${esc(query)}" placeholder="${esc(placeholder)}" maxlength="100"></label><button class="school-button secondary" type="submit">Rechercher</button>${query?button('Effacer','clear-search'):''}</form>`;

export function loginHTML(error=''){
 return `<a class="skip-link" href="#main">Aller à la connexion</a><div class="school-login-layout"><div class="school-login-story">${brand('fr')}<span class="school-badge purple">L’ESPACE ÉCOLE</span><h1>Chaque progrès<br>mérite un <em>suivi.</em></h1><p>Apprendre, accompagner, enseigner.<br>Un même espace. Le bon point de vue.</p><div class="school-login-illustration" aria-hidden="true"><div class="school-illustration-top"><span>LA PROCHAINE ÉTAPE</span><span>↗</span></div><div class="school-illustration-ring"><svg viewBox="0 0 130 130"><circle cx="65" cy="65" r="52" fill="none" stroke="#ece5fa" stroke-width="10"/><circle cx="65" cy="65" r="52" fill="none" stroke="#6840d8" stroke-width="10" stroke-dasharray="214 327" transform="rotate(-90 65 65)" stroke-linecap="round"/></svg><div><strong>On avance.</strong><span>À votre rythme.</span></div></div><div class="school-illustration-task"><span>01</span><div><strong>Comprendre</strong><small>Une idée expliquée simplement.</small></div><b>✓</b></div><div class="school-illustration-task"><span>02</span><div><strong>Pratiquer</strong><small>Un exercice, puis un retour utile.</small></div><b>↗</b></div><div class="school-illustration-note">Le petit déclic d’aujourd’hui.<br>Les bases solides de demain.</div></div><a class="school-back-link" href="index.html">← Retour au site Numeria</a></div><main id="main" class="school-login-card"><div class="school-login-heading"><span class="school-badge lime">Démonstration locale</span><h2>Votre espace Numeria.</h2><p>Choisissez un compte test ou saisissez ses identifiants.</p></div><div class="school-test-accounts">${DEMO_ACCOUNTS.slice(0,6).map(u=>`<button data-school-action="pick-account" data-id="${u.id}" class="school-account-pick"><span class="school-role-symbol">${icon(u.role==='admin'?'chart':u.role==='teacher'?'book':u.role==='parent'?'nodes':'code')}</span><strong>${ROLES[u.role]}</strong><small>${esc(u.email)}</small></button>`).join('')}</div><form data-school-form="login" class="school-form"><div class="school-fields">${field('Adresse du compte test',input('email','','email','required autocomplete="username" maxlength="120"'))}${field('Mot de passe',`<div class="school-password-field">${input('password','','password','required autocomplete="current-password"')}<button type="button" data-school-action="show-password" aria-label="Afficher le mot de passe">Afficher</button></div>`)}</div><p class="school-login-error" role="alert">${esc(error)}</p>${saveButton('Entrer dans mon espace')}</form><div class="school-demo-password"><span>Mot de passe commun à tous les comptes</span><code>${DEMO_PASSWORD}</code></div><p class="school-demo-explainer">Comptes et données fictifs. Les changements et PDF restent sur cet appareil. Cet accès de démonstration ne protège aucune donnée réelle et n’envoie aucun message.</p></main></div>`;
}
export function shellHTML(s,actor,screen='overview',opts={}){
 const nav=NAV[actor.role],item=nav.find(n=>n[0]===screen)||nav[0],unread=s.messages.filter(m=>m.recipientId===actor.id&&!m.readBy.includes(actor.id)).length;
 const navHTML=nav.map(([key,label,ico])=>`<button data-school-screen="${key}" class="${screen===key?'active':''}" ${screen===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${key==='messages'&&unread?`<b>${unread}</b>`:''}</button>`).join('');
 return `<a class="skip-link" href="#school-main">Aller au tableau de bord</a><div class="school-shell"><aside class="school-sidebar">${brand('fr')}<div class="school-sidebar-role">${ROLES[actor.role]}</div><nav aria-label="Espace ${ROLES[actor.role]}">${navHTML}</nav><div class="school-sidebar-foot"><a href="index.html">${icon('external')}Voir la vitrine</a><button data-school-action="logout">${icon('lock')}Changer de compte</button></div></aside><div class="school-workspace"><header class="school-topbar"><button class="school-mobile-menu school-icon-button" data-school-action="menu" aria-label="Ouvrir la navigation">${icon('menu')}</button><div class="school-topbar-location"><span>NUMERIA / MON ESPACE</span><strong>${item[1]}</strong></div><div class="school-topbar-tools"><span class="school-save-state">${opts.mode==='persistent'?'Sauvegarde locale active':'Sauvegarde temporaire'}</span><button class="school-icon-button" data-school-screen="messages" aria-label="Messages : ${unread} non lus">${icon('mail')}${unread?'<i></i>':''}</button><button class="school-user-chip" data-school-action="logout" aria-label="Changer de compte, connecté comme ${esc(actor.name)}"><span>${esc(actor.name.split(' ')[0].slice(0,2).toUpperCase())}</span><strong>${esc(actor.name.split(' · ')[0])}</strong></button></div></header><div class="school-demo-strip">${icon('help')}<p><strong>Espace de démonstration.</strong> Données fictives, paiements et messagerie simulés. Sauvegarde sur cet appareil, sans publication automatique sur Internet.</p></div>${opts.mode!=='persistent'?'<div class="school-memory-warning" role="status">Le navigateur refuse la sauvegarde. Vos changements disparaîtront en fermant cette page.</div>':''}<main id="school-main" tabindex="-1" class="school-main">${screenHTML(s,actor,screen,opts)}</main><footer class="school-app-footer"><span>NUMERIA · Comprendre. Construire. Progresser.</span><span>Horaires affichés : Algérie (UTC+1)</span></footer></div></div><dialog id="school-dialog" class="school-dialog" aria-labelledby="school-dialog-title"><div class="school-dialog-top"><span>NUMERIA / MON ESPACE</span><button class="school-icon-button" data-school-action="close" aria-label="Fermer">${icon('close')}</button></div><div id="school-dialog-body"></div></dialog><dialog id="school-menu" class="school-mobile-nav" aria-labelledby="school-menu-title"><div class="school-dialog-top"><h2 id="school-menu-title">${ROLES[actor.role]}</h2><button class="school-icon-button" data-school-action="close-menu" aria-label="Fermer le menu">${icon('close')}</button></div><nav aria-label="Navigation mobile">${navHTML}</nav><a href="index.html">Voir la vitrine ↗</a><button class="school-button secondary" data-school-action="logout">Changer de compte</button></dialog><div id="school-toast" class="school-toast" role="status" aria-live="polite"></div>`;
}
function scopedActor(actor,opts){return actor.role==='parent'&&actor.children.includes(opts.child)?{...actor,children:[opts.child]}:actor;}
export function screenHTML(s,rawActor,screen,opts={}){
 const actor=scopedActor(rawActor,opts),renderer={overview,courses:coursesScreen,people:peopleScreen,resources:resourcesScreen,assignments:assignmentsScreen,calendar:calendarScreen,attendance:attendanceScreen,finance:financeScreen,messages:messagesScreen,followup:followupScreen,content:contentScreen,settings:settingsScreen};
 const parentPicker=rawActor.role==='parent'?`<div class="school-child-picker"><label>Suivi de ${select('child',[['all','Tous mes enfants'],...rawActor.children.map(id=>[id,name(s,id)])],opts.child||'all','data-school-child')}</label></div>`:'';
 return `${parentPicker}${(renderer[screen]||overview)(s,actor,opts)}`;
}
function overview(s,actor){
 const m=metrics(s,actor),learner=LEARNERS.includes(actor.role),admin=actor.role==='admin',teacher=actor.role==='teacher',cids=courseIds(s,actor),ids=learnerIds(s,actor);
 const en=s.enrollments.filter(e=>ids.includes(e.userId)&&cids.includes(e.courseId));
 const upcoming=s.sessions.filter(x=>cids.includes(x.courseId)&&Date.parse(x.start)>=Date.now()).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start)).slice(0,3);
 const greeting=actor.role==='parent'?'Un regard clair sur leurs progrès.':admin?'L’école, dans tous ses détails.':teacher?'Du temps pour enseigner.':actor.role==='lycee'?'Un peu plus solide à chaque séance.':actor.role==='professional'?'Apprendre pour mieux construire.':'La prochaine étape vous attend.';
 const stats=admin?[[m.learners,'apprenants actifs','nodes'],[m.courses,'formations au catalogue','book'],[money(m.paid),'encaissés fictifs','cart'],[money(m.pending),'à régler en démo','clock']]:teacher?[[m.learners,'apprenants suivis','nodes'],[m.courses,'groupes attribués','book'],[m.ungraded,'copies à corriger','code'],[m.attendance===null?'—':m.attendance+'%','présences saisies','check']]:[[m.progress+'%','modules parcourus (démo)','chart'],[m.grade===null?'—':m.grade.toFixed(1)+'/20','moyenne des devoirs notés','code'],[m.attendance===null?'—':m.attendance+'%','présences saisies','check'],[upcoming.length,'séances à venir affichées','clock']];
 return `<div class="school-welcome"><div><span class="eyebrow">${dateLabel(new Date().toISOString())} / ${ROLES[actor.role]}</span><h1>Bonjour, ${esc(actor.name.split(' · ')[0].split(' ')[0])}.</h1><p>${greeting}</p></div>${admin?button('Créer un compte +','user-new','','primary'):teacher?button('Créer un devoir +','assignment-new','','primary'):button(learner?'Continuer mon parcours':'Voir les bulletins',learner?'go-courses':'go-followup','','primary')}</div><div class="school-metrics">${stats.map(([value,label,i])=>`<article>${icon(i)}<strong>${value}</strong><span>${label}</span></article>`).join('')}</div><div class="school-dashboard-grid"><section class="school-card school-priority"><div class="school-card-heading"><span class="eyebrow">LA PROCHAINE ÉTAPE</span>${badge('On avance','purple')}</div><h2>${admin?'Les points à suivre.':teacher?'Un retour fait la différence.':learner?'La régularité fait le reste.':'Les petits signaux comptent.'}</h2><p>${admin?`${m.ungraded} copie(s) attendent un retour. ${s.resources.filter(r=>r.status==='draft').length} ressource(s) restent en brouillon.`:teacher?`${m.ungraded} copie(s) à corriger. Un retour précis aide à savoir quoi reprendre.`:learner?'Reprenez un module, testez votre compréhension et gardez une trace de ce que vous devez retravailler.':'Un progrès se lit dans le travail réalisé, la présence et la qualité du raisonnement, pas dans une seule note.'}</p><div class="school-priority-actions"><button class="school-button ink" data-school-screen="${admin||teacher?'assignments':learner?'courses':'followup'}">${admin||teacher?'Ouvrir les corrections':learner?'Ouvrir mes cours':'Consulter le suivi'}${icon('arrow')}</button><span>Une action utile, aujourd’hui.</span></div><span class="school-priority-spark" aria-hidden="true">✳</span></section><section class="school-card"><div class="school-card-heading"><h2>À l’agenda</h2><button class="school-text-button" data-school-screen="calendar">Tout voir ↗</button></div>${upcoming.length?upcoming.map(x=>sessionRow(s,x)).join(''):empty('Aucune séance à venir','Les nouvelles séances apparaîtront ici.')}</section><section class="school-card"><div class="school-card-heading"><h2>${admin?'Le rythme des encaissements fictifs':teacher?'Progression des groupes':'Les parcours en cours'}</h2>${admin?button('Exporter CSV','export-finance'):''}</div>${admin?financeChart(s):en.slice(0,5).map(e=>enrollmentRow(s,e,!learner)).join('')||empty('Aucun parcours attribué','L’administration peut ajouter une inscription de démonstration.')}</section><section class="school-card"><div class="school-card-heading"><h2>${admin?'L’activité de l’école':'Le fil Numeria'}</h2>${admin?button('Publier une annonce','announcement-new'):''}</div>${s.announcements.slice(0,2).map(a=>`<article class="school-announcement"><span>${dateLabel(a.createdAt)}</span><h3>${esc(a.title)}</h3><p>${esc(a.text)}</p></article>`).join('')}${admin?`<div class="school-audit-mini">${s.audit.slice(0,3).map(a=>`<p><strong>${esc(a.action)}</strong><span>${esc(a.detail)}</span></p>`).join('')}</div>`:`<div class="school-coach-note">${icon('bolt')}<p>Question bloquante ? Envoyez-la au professeur avec votre démarche, même incomplète.</p><button data-school-screen="messages" class="school-text-button">Ouvrir la messagerie →</button></div>`}</section></div>`;
}
function financeChart(s){
 const now=new Date(),months=Array.from({length:6},(_,i)=>new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()-5+i,1))),values=months.map(d=>s.invoices.filter(x=>x.status==='paid'&&new Date(x.paidAt).getUTCFullYear()===d.getUTCFullYear()&&new Date(x.paidAt).getUTCMonth()===d.getUTCMonth()).reduce((n,x)=>n+x.amount,0)),max=Math.max(...values,1);
 return `<div class="school-bar-chart" role="img" aria-label="Encaissements fictifs par mois : ${esc(months.map((d,i)=>`${d.toLocaleDateString('fr-FR',{month:'long',timeZone:'UTC'})} ${values[i]} DA`).join(', '))}">${months.map((d,i)=>`<div><strong>${values[i]?money(values[i]):'0'}</strong><span class="school-chart-bar" style="height:${Math.max(3,values[i]/max*140)}px"></span><small>${d.toLocaleDateString('fr-FR',{month:'short',timeZone:'UTC'})}</small></div>`).join('')}</div><p class="school-caption">Somme des échéances marquées « payée en démo », par date de règlement. Aucune transaction réelle.</p>`;
}
function enrollmentRow(s,e,showName=false){const n=progress(s,e);return `<div class="school-enrollment-row"><div><strong>${esc(courseName(s,e.courseId))}</strong><span>${showName?esc(name(s,e.userId)):`${e.completed.length} / ${findCourse(s,e.courseId).modules.length} modules parcourus`}</span></div><b>${n}%</b>${moduleBar(n)}</div>`;}
function sessionRow(s,x){return `<button class="school-session-row" data-school-action="session-open" data-id="${x.id}"><span class="school-session-day"><b>${new Intl.DateTimeFormat('fr-FR',{day:'2-digit',timeZone:'Africa/Algiers'}).format(new Date(x.start))}</b><small>${new Intl.DateTimeFormat('fr-FR',{month:'short',timeZone:'Africa/Algiers'}).format(new Date(x.start))}</small></span><span><strong>${esc(x.title)}</strong><small>${dateLabel(x.start,true)} · ${x.duration} min</small></span>${icon('arrow')}</button>`;}

function coursesScreen(s,actor,opts){
 const admin=actor.role==='admin',teacher=actor.role==='teacher',ids=courseIds(s,actor),items=s.courses.filter(c=>ids.includes(c.id)&&matches(c.title.fr,opts.query));
 return `${panelHeading(admin?'Un catalogue qui se construit.':teacher?'Vos groupes, vos objectifs.':'Comprendre, puis pratiquer.',admin?'Modifiez le catalogue et choisissez ce qui apparaît sur la vitrine de cet appareil.':teacher?'Retrouvez les parcours attribués et les apprenants inscrits.':'Les leçons proposent des objectifs, un extrait pédagogique et un quiz de démonstration. Les contenus complets restent à produire.',admin?button('Ajouter une formation +','course-new','','primary'):'')}${search(opts.query||'','Rechercher une formation')}<div class="school-course-grid">${items.map(c=>{const en=s.enrollments.filter(e=>e.courseId===c.id&&learnerIds(s,actor).includes(e.userId)),own=en.find(e=>e.userId===actor.id);return `<article class="school-course-card"><div class="school-course-art ${c.audience==='lycee'?'math':'tech'}"><span>${esc(c.audience==='lycee'?'x²':c.category==='ai'?'AI':'</>')}</span><small>${c.audience==='lycee'?'COMPRENDRE LE RAISONNEMENT':'CONSTRUIRE AVEC MÉTHODE'}</small></div><div class="school-course-card-body"><div class="school-card-heading">${badge(c.status==='draft'?'Brouillon':'Publié',c.status==='draft'?'amber':'purple')}<small>${c.modules.length} modules</small></div><h2>${esc(c.title.fr)}</h2><p>${esc(c.description.fr)}</p><div class="school-course-meta"><span>${c.weeks} sem. · ${c.live} h en direct</span><strong>${money(c.price)}${c.monthly?' / mois':''}</strong></div>${own?`${moduleBar(progress(s,own))}<div class="school-course-progress-label">${own.completed.length} / ${c.modules.length} modules parcourus en démo</div>`:`<div class="school-course-progress-label">${en.length} apprenant(s) dans ce groupe · ${esc(name(s,c.teacherId))}</div>`}<div class="school-row-actions">${admin?button('Modifier','course-edit',c.id):button(own?'Continuer':'Explorer les modules','course-open',c.id,'primary')}${admin?button('Aperçu','course-open',c.id):''}${teacher?button('Voir le groupe','group-open',c.id):''}</div></div></article>`;}).join('')||empty('Aucun parcours','Essayez une autre recherche ou demandez une attribution à l’administration.')}</div>`;
}
function peopleScreen(s,actor,opts){return `${panelHeading('La bonne personne, au bon endroit.','Comptes fictifs, inscriptions et liens parent-enfant. Aucun e-mail d’invitation n’est envoyé.',button('Créer un compte +','user-new','','primary'))}${search(opts.query||'','Rechercher un nom, un e-mail ou un rôle')}<div class="school-people-grid">${s.users.filter(u=>matches(`${u.name} ${u.email} ${ROLES[u.role]}`,opts.query)).map(u=>`<article class="school-card school-person"><div class="school-card-heading"><span class="school-person-avatar">${esc(u.name.slice(0,2).toUpperCase())}</span>${badge(u.active?'Actif en démo':'Désactivé',u.active?'purple':'amber')}</div><h2>${esc(u.name)}</h2><p>${ROLES[u.role]}</p><code>${esc(u.email)}</code><div class="school-person-links">${LEARNERS.includes(u.role)?`${s.enrollments.filter(e=>e.userId===u.id).length} parcours attribué(s)`:u.role==='parent'?`${u.children.length} enfant(s) lié(s)`:u.role==='teacher'?`${s.courses.filter(c=>c.teacherId===u.id).length} formation(s) attribuée(s)`:'Pilotage de l’école'}</div>${button('Gérer le compte','user-edit',u.id)}${LEARNERS.includes(u.role)?button('Télécharger le bulletin','report-user',u.id):''}</article>`).join('')}</div>`;}
function resourcesScreen(s,actor,opts){const edit=['admin','teacher'].includes(actor.role),items=visibleResources(s,actor).filter(r=>matches(`${r.title} ${courseName(s,r.courseId)}`,opts.query));return `${panelHeading('La bibliothèque, à portée de main.','Extraits réels et PDF ajoutés sur cet appareil. Les collections complètes ne sont pas encore distribuées.',edit?button('Ajouter un PDF +','resource-new','','primary'):'')}${search(opts.query||'','Rechercher une ressource')}<div class="school-resource-grid">${items.map(r=>`<article class="school-card school-resource"><div class="school-card-heading"><span class="school-resource-glyph">${icon(r.fileId?'download':'code')}</span>${badge(r.status==='published'?'Publié':'Brouillon',r.status==='published'?'purple':'amber')}</div><small>${esc(courseName(s,r.courseId))}</small><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><div class="school-resource-info">${r.fileId?`PDF · ${(r.size/1024).toFixed(0)} Ko`:'Extrait gratuit téléchargeable'}${r.public?' · visible sur la vitrine locale':''}</div><div class="school-row-actions">${button('Télécharger','resource-download',r.id,'primary')}${edit&&(actor.role==='admin'||r.ownerId===actor.id)?button('Modifier','resource-edit',r.id):''}</div></article>`).join('')||empty('Pas encore de ressource','Le professeur ou l’administration peut ajouter un PDF au parcours.')}</div>`;}
function assignmentsScreen(s,actor,opts){
 const cids=courseIds(s,actor),ids=learnerIds(s,actor),edit=['admin','teacher'].includes(actor.role),learner=LEARNERS.includes(actor.role),items=s.assignments.filter(a=>cids.includes(a.courseId)&&matches(`${a.title} ${courseName(s,a.courseId)}`,opts.query));
 return `${panelHeading(edit?'Un retour précis fait avancer.':actor.role==='parent'?'Le travail et les retours.':'Le prochain exercice utile.',edit?'Créez un devoir, corrigez une copie et donnez une prochaine étape concrète.':'Retrouvez les consignes, les échéances et les corrections du professeur.',edit?button('Créer un devoir +','assignment-new','','primary'):'')}${search(opts.query||'','Rechercher un devoir')}<div class="school-assignment-list">${items.map(a=>{const subs=s.submissions.filter(x=>x.assignmentId===a.id&&ids.includes(x.userId)),own=subs.find(x=>x.userId===actor.id);return `<article class="school-card school-assignment"><div class="school-card-heading"><span class="eyebrow">${esc(courseName(s,a.courseId))}</span>${badge(`À rendre le ${dateLabel(a.due)}`)}</div><h2>${esc(a.title)}</h2><p>${esc(a.body)}</p><div class="school-rubric">${esc(a.rubric)}</div>${learner?`<div class="school-row-actions">${button(own?'Voir / modifier ma copie':'Rendre mon devoir','assignment-open',a.id,'primary')}${badge(own?own.grade===null?'Reçu · à corriger':`${own.grade}/20`:'À faire',own?.grade!==null&&own?'purple':'amber')}</div>`:`<div class="school-submission-list">${subs.length?subs.map(x=>`<div><span><strong>${esc(name(s,x.userId))}</strong><small>${x.grade===null?'À corriger':`${x.grade}/20 · ${esc(x.feedback)}`}</small></span>${button(edit?'Ouvrir la copie':'Voir le retour',edit?'grade-open':'submission-open',x.id)}</div>`).join(''):'<p>Aucune copie reçue pour les apprenants suivis.</p>'}</div>`}</article>`;}).join('')||empty('Aucun devoir','Les exercices attribués apparaîtront ici.')}</div>`;
}
function calendarScreen(s,actor){const cids=courseIds(s,actor),edit=['admin','teacher'].includes(actor.role),items=s.sessions.filter(x=>cids.includes(x.courseId)).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start));return `${panelHeading('Un agenda qui laisse de la place au travail.','Dates et horaires de démonstration. Un fichier calendrier peut être téléchargé ; aucune invitation n’est envoyée.',`<div class="school-row-actions">${button('Exporter .ics','calendar-export')}${edit?button('Ajouter une séance +','session-new','','primary'):''}</div>`)}<div class="school-calendar-grid"><section class="school-card"><h2>À venir</h2>${items.filter(x=>Date.parse(x.start)>=Date.now()).map(x=>sessionRow(s,x)).join('')||empty('Agenda libre','Aucune séance planifiée.')}</section><section class="school-card"><h2>Historique des séances</h2>${items.filter(x=>Date.parse(x.start)<Date.now()).reverse().map(x=>sessionRow(s,x)).join('')||empty('Pas de séance passée','L’historique apparaîtra ici.')}</section></div>`;}
function attendanceScreen(s,actor){const edit=['admin','teacher'].includes(actor.role),cids=courseIds(s,actor),ids=learnerIds(s,actor),items=s.sessions.filter(x=>cids.includes(x.courseId)&&Date.parse(x.start)<=Date.now()).sort((a,b)=>Date.parse(b.start)-Date.parse(a.start));return `${panelHeading('La présence, avec du contexte.','Une absence justifiée reste une absence. Le taux de présence compte les présences et retards parmi les séances renseignées.')}<div class="school-attendance-list">${items.map(x=>`<section class="school-card"><div class="school-card-heading"><div><h2>${esc(x.title)}</h2><p>${dateLabel(x.start,true)}</p></div>${edit?button('Saisir les présences','attendance-open',x.id):''}</div><div class="school-attendance-rows">${s.enrollments.filter(e=>e.courseId===x.courseId&&ids.includes(e.userId)).map(e=>{const a=s.attendance.find(a=>a.sessionId===x.id&&a.userId===e.userId);return `<div><strong>${esc(name(s,e.userId))}</strong>${badge(a?labels[a.status]:'Non renseigné',a?.status==='absent'?'amber':a?.status==='present'?'purple':'')}</div>`;}).join('')||'<p>Aucun apprenant inscrit.</p>'}</div></section>`).join('')||empty('Rien à saisir pour le moment','Les présences sont renseignées après le début de la séance.')}</div>`;}
function financeScreen(s,actor){const ids=learnerIds(s,actor),items=s.invoices.filter(i=>ids.includes(i.userId)),m=metrics(s,actor);return `${panelHeading('Des échéances lisibles.','Toutes les sommes ci-dessous sont fictives. Aucun débit, reçu légal ou encaissement réel.',actor.role==='admin'?button('Créer une échéance +','invoice-new','','primary'):'')}<div class="school-finance-totals"><div><span>Réglé en démonstration</span><strong>${money(m.paid)}</strong></div><div><span>Restant en démonstration</span><strong>${money(m.pending)}</strong></div>${actor.role==='admin'?button('Exporter CSV','export-finance'):''}</div><div class="school-invoice-list">${items.map(i=>`<article class="school-card school-invoice"><div><span class="eyebrow">${esc(i.reference)}</span><h2>${esc(courseName(s,i.courseId))}</h2><p>${esc(name(s,i.userId))} · Échéance ${dateLabel(i.due)}</p></div><div><strong>${money(i.amount)}</strong>${badge(i.status==='paid'?`Payée en démo · ${i.method==='cash'?'espèces':'Edahabia'}`:'À régler en démo',i.status==='paid'?'purple':'amber')}${i.status==='pending'?button('Simuler un règlement','invoice-pay',i.id,'primary'):button('Télécharger le récapitulatif démo','invoice-receipt',i.id)}</div></article>`).join('')||empty('Aucune échéance','L’administration peut en ajouter dans cet espace.')}</div>`;}
function messagesScreen(s,actor){const items=s.messages.filter(m=>m.senderId===actor.id||m.recipientId===actor.id).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt)),recipients=messageRecipients(s,actor);return `${panelHeading('Une question bien posée. Un retour utile.','Messagerie locale de démonstration : aucun e-mail ni notification externe n’est envoyé.')}<div class="school-message-grid"><section class="school-card"><h2>Écrire un message</h2>${recipients.length?`<form data-school-form="message-save" class="school-form">${field('Destinataire',select('recipientId',recipients.map(u=>[u.id,`${u.name} · ${ROLES[u.role]}`]),'','required'))}${field('Votre message',textarea('text','',6,'required minlength="2" maxlength="4000"'))}${saveButton('Enregistrer le message démo')}</form>`:empty('Pas de destinataire','Demandez à l’administration d’attribuer un professeur.')}</section><section class="school-card"><div class="school-card-heading"><h2>Échanges</h2>${button('Tout marquer comme lu','messages-read')}</div>${items.length?items.map(m=>`<article class="school-message ${m.senderId===actor.id?'sent':''}"><div><strong>${esc(name(s,m.senderId))}</strong><span>${dateLabel(m.createdAt,true)}</span></div><small>À ${esc(name(s,m.recipientId))}${m.recipientId===actor.id&&!m.readBy.includes(actor.id)?' · non lu':''}</small><p>${esc(m.text).replace(/\n/g,'<br>')}</p>${m.senderId!==actor.id?`<button class="school-text-button" data-school-action="reply" data-id="${m.senderId}">Répondre →</button>`:''}</article>`).join(''):empty('La discussion commence ici','Les messages échangés apparaîtront dans cette liste.')}</section></div>`;}
function followupScreen(s,actor){return `${panelHeading('Voir les progrès. Savoir quoi reprendre.','Les indicateurs proviennent des données fictives enregistrées dans cet espace. Ils ne prédisent aucun résultat scolaire.')}<div class="school-followup-grid">${actor.children.map(id=>{const child=s.users.find(u=>u.id===id),m=metrics(s,child),en=s.enrollments.filter(e=>e.userId===id),subs=s.submissions.filter(x=>x.userId===id&&x.grade!==null);return `<section class="school-card"><div class="school-card-heading"><h2>${esc(child.name)}</h2>${button('Télécharger le bulletin','report-user',id)}</div><div class="school-child-stats"><span><b>${m.progress}%</b> Modules parcourus</span><span><b>${m.grade===null?'—':m.grade.toFixed(1)+'/20'}</b> Moyenne</span><span><b>${m.attendance===null?'—':m.attendance+'%'}</b> Présences saisies</span></div>${en.map(e=>enrollmentRow(s,e)).join('')}<div class="school-feedback"><h3>Les derniers retours</h3>${subs.length?subs.map(x=>`<p><strong>${x.grade}/20 · ${esc(s.assignments.find(a=>a.id===x.assignmentId)?.title)}</strong>${esc(x.feedback)}</p>`).join(''):'<p>Aucun devoir noté pour le moment.</p>'}</div><div class="school-next-step"><strong>La prochaine étape</strong><p>${s.attendance.some(a=>a.userId===id&&a.status==='absent')?'Reprendre le contenu de la séance manquée avec le professeur, puis vérifier les points bloquants.':'Garder des séances de travail courtes et régulières, puis noter les questions à poser au professeur.'}</p></div></section>`;}).join('')||empty('Aucun enfant lié','L’administration peut associer les comptes des enfants au compte parent.')}</div>`;}
export const SITE_FIELDS=[['hero1','Accueil · ligne 1'],['hero2','Accueil · ligne 2'],['hero3','Accueil · mot accentué'],['heroLead','Accueil · introduction'],['schoolHero1','Lycée · titre 1'],['schoolHero2','Lycée · titre 2'],['schoolHeroCopy','Lycée · introduction'],['techHero1','Formations · titre 1'],['techHero2','Formations · titre 2'],['techHeroCopy','Formations · introduction'],['resourcesHero1','Ressources · titre 1'],['resourcesHero2','Ressources · titre 2'],['resourcesHeroCopy','Ressources · introduction'],['helpTitle','Contact · titre'],['helpCopy','Contact · introduction']];
function contentScreen(s){return `${panelHeading('Une vitrine qui suit votre école.','Les textes modifiés apparaissent sur la vitrine dans ce navigateur. Pour les publier pour tous, il faudra intégrer ces données à un serveur ou au dépôt GitHub.',button('Ajouter une annonce +','announcement-new','','primary'))}<section class="school-card"><form data-school-form="site-save" class="school-form"><div class="school-fields">${field('Langue des textes',select('language',[['fr','Français'],['en','English'],['ar','العربية']],'fr','data-content-language'))}${field('Champ à modifier',select('key',SITE_FIELDS,'heroLead','data-content-key'))}${field('Contenu',textarea('value',s.site.heroLead?.fr||messages.heroLead.fr,5,'required maxlength="1600" data-content-value'),true)}</div>${saveButton('Enregistrer sur cet appareil')}</form><p class="school-caption">Les autres traductions restent intactes. Le nom et l’adresse de contact ne sont pas remplacés par des données de test.</p><a href="index.html" class="school-button secondary">Voir la vitrine locale ↗</a></section><section class="school-card school-announcements-editor"><h2>Annonces de l’espace école</h2>${s.announcements.map(a=>`<article class="school-announcement"><span>${dateLabel(a.createdAt)}</span><h3>${esc(a.title)}</h3><p>${esc(a.text)}</p></article>`).join('')}</section>`;}
function settingsScreen(s){return `${panelHeading('Gardez une copie de votre travail.','La sauvegarde JSON contient les comptes fictifs, le catalogue, les progrès et les PDF. Elle peut être restaurée sur un autre navigateur.')}<div class="school-settings-grid"><section class="school-card"><span class="school-badge purple">SAUVEGARDE COMPLÈTE</span><h2>Exporter, puis restaurer.</h2><p>Jusqu’à 20 Mo de PDF au total, 5 Mo par fichier. Conservez vos exports : effacer les données du navigateur supprime cette démonstration.</p>${button('Télécharger la sauvegarde JSON','backup-export','','primary')}<form data-school-form="backup-import" class="school-form">${field('Restaurer une sauvegarde Numeria',input('backup','','file','accept="application/json,.json" required'))}<label class="school-checkbox"><input type="checkbox" required name="confirm"> Remplacer toutes les données démo de cet appareil.</label>${saveButton('Restaurer la sauvegarde')}</form></section><section class="school-card"><span class="school-badge lime">VERS UNE VRAIE ÉCOLE</span><h2>Le socle est défini.</h2><p>Une mise en service réelle nécessite une authentification côté serveur, des permissions vérifiées, une base de données partagée et un stockage de fichiers privé. Le code et les règles de ce prototype préparent cette étape.</p><p>Les accès tests sont publics. N’ajoutez aucune donnée personnelle, copie d’élève réelle ou document confidentiel.</p>${button('Réinitialiser les données fictives','reset-open')}<p class="school-caption">La réinitialisation concerne uniquement l’espace école local, pas le site publié ni le panier de la vitrine.</p></section></div><section class="school-card school-log"><div class="school-card-heading"><h2>Journal des opérations</h2><span>${s.audit.length} opérations conservées</span></div><div class="school-log-rows">${s.audit.map(a=>`<div><span>${dateLabel(a.at,true)}</span><strong>${esc(a.action)}</strong><p>${esc(a.detail)} · ${esc(name(s,a.actorId))}</p></div>`).join('')}</div></section>`;}

const dialogHeading=(title,copy='')=>`<h2 id="school-dialog-title" tabindex="-1">${esc(title)}</h2>${copy?`<p class="school-dialog-intro">${esc(copy)}</p>`:''}`;
export function userForm(s,id=''){
 const u=s.users.find(u=>u.id===id),role=u?.role||'student',en=s.enrollments.filter(e=>e.userId===id).map(e=>e.courseId);
 return `${dialogHeading(u?'Gérer ce compte test':'Créer un compte test','Utilisez une identité fictive et une adresse @numeria.dz. Aucun compte réel ni e-mail d’invitation ne sera créé.')}<form data-school-form="user-save" data-id="${esc(id)}" class="school-form"><div class="school-fields">${field('Nom fictif',input('name',u?.name||'','text','required maxlength="100"'))}${field('Adresse fictive @numeria.dz',input('email',u?.email||'','email','required maxlength="120"'))}${field('Rôle',select('role',Object.entries(ROLES),role,u?'disabled':'data-account-role'))}${u?input('role',role,'hidden'):''}${field('Statut',select('active',[['true','Actif en démo'],['false','Désactivé']],String(u?.active!==false)))}</div><fieldset class="school-choice-set" data-role-courses ${!LEARNERS.includes(role)?'hidden':''}><legend>Formations attribuées à cet apprenant</legend>${s.courses.map(c=>`<label class="school-checkbox"><input type="checkbox" name="courses" value="${c.id}" ${en.includes(c.id)?'checked':''}> ${esc(c.title.fr)}</label>`).join('')}</fieldset><fieldset class="school-choice-set" data-role-children ${role!=='parent'?'hidden':''}><legend>Enfants liés à ce parent</legend>${s.users.filter(u=>LEARNERS.includes(u.role)).map(child=>`<label class="school-checkbox"><input type="checkbox" name="children" value="${child.id}" ${u?.children.includes(child.id)?'checked':''}> ${esc(child.name)}</label>`).join('')}</fieldset><div class="school-demo-password"><span>Mot de passe du compte de démonstration</span><code>${DEMO_PASSWORD}</code></div>${saveButton('Enregistrer le compte test')}</form>`;
}
export function courseForm(s,id=''){
 const old=findCourse(s,id),base=old||s.courses.find(c=>c.id==='python');
 return `${dialogHeading(old?'Modifier la formation':'Ajouter une formation','Les nouvelles formations sont des programmes à préparer. Publier ici met à jour le catalogue dans ce navigateur uniquement.')}<form data-school-form="course-save" data-id="${esc(id)}" class="school-form"><div class="school-fields">${field('Gabarit pédagogique',select('source',TEMPLATE_COURSES.map(c=>[c.id,copy(c.title)]),base.source,'data-course-template'))}${field('Visibilité',select('status',[['draft','Brouillon'],['published','Publié sur cet appareil']],old?.status||'draft'))}${field('Titre en français',input('titleFr',old?.title.fr||'','text','required maxlength="180"'),true)}${field('Présentation en français',textarea('descriptionFr',old?.description.fr||'',3,'required maxlength="1600"'),true)}${field('Prix en DA',input('price',base.price,'number','required min="0" max="10000000" step="1"'))}${field('Durée en semaines',input('weeks',base.weeks,'number','required min="1" max="52"'))}${field('Heures en direct',input('live',base.live,'number','required min="1" max="1000"'))}${field('Pratique estimée (heures)',input('practice',base.practice,'number','required min="0" max="2000"'))}${field('Professeur attribué',select('teacherId',s.users.filter(u=>u.role==='teacher'&&u.active).map(u=>[u.id,u.name]),base.teacherId,'required'),true)}${field('Programme · une ligne par module : Titre | Objectif',textarea('modules',base.modules.map(m=>`${m.title} | ${m.text}`).join('\n'),7,'required maxlength="100000"'),true)}</div><details class="school-translations"><summary>Traductions anglaise et arabe</summary><div class="school-fields">${field('Title · English',input('titleEn',old?.title.en||'','text','maxlength="180"'))}${field('العنوان · العربية',input('titleAr',old?.title.ar||'','text','maxlength="180" dir="rtl"'))}${field('Description · English',textarea('descriptionEn',old?.description.en||'',3,'maxlength="1600"'))}${field('الوصف · العربية',textarea('descriptionAr',old?.description.ar||'',3,'maxlength="1600" dir="rtl"'))}</div></details><p class="school-caption">Sans traduction, les nouveaux textes utilisent le français. Les objectifs des modules modifiés sont saisis en français.</p>${saveButton('Enregistrer la formation')}</form>`;
}
export function resourceForm(s,actor,id=''){
 const r=s.resources.find(r=>r.id===id),allowed=s.courses.filter(c=>courseIds(s,actor).includes(c.id));
 return `${dialogHeading(r?'Modifier la ressource':'Ajouter un PDF','Le fichier et ses métadonnées sont enregistrés ensemble sur cet appareil. N’ajoutez aucun document confidentiel.')}<form data-school-form="resource-save" data-id="${esc(id)}" class="school-form"><div class="school-fields">${field('Titre',input('title',r?.title||'','text','required maxlength="200"'),true)}${field('Formation associée',select('courseId',allowed.map(c=>[c.id,c.title.fr]),r?.courseId,'required'))}${field('Visibilité',select('status',[['draft','Brouillon'],['published','Disponible dans les espaces autorisés']],r?.status||'draft'))}${field('Description',textarea('description',r?.description||'',3,'maxlength="1600"'),true)}${field(r?'Remplacer le fichier par un PDF (facultatif)':'PDF · 5 Mo maximum',input('pdf','','file',`accept="application/pdf,.pdf" ${r?'':'required'}`),true)}</div>${actor.role==='admin'?`<label class="school-checkbox"><input name="public" type="checkbox" ${r?.public?'checked':''}> Afficher ce support gratuit sur la vitrine de cet appareil.</label>`:''}<p class="school-caption">${r?.sampleFile?'L’extrait existant reste disponible si aucun PDF n’est ajouté.':''} Seuls les PDF avec une signature valide sont acceptés. Les ressources privées du rôle restent hors de la vitrine.</p>${saveButton('Enregistrer la ressource')}${r?button('Supprimer cette ressource démo','resource-delete',r.id):''}</form>`;
}
export function assignmentForm(s,actor){return `${dialogHeading('Un devoir, un objectif clair.')}<form data-school-form="assignment-save" class="school-form"><div class="school-fields">${field('Formation',select('courseId',s.courses.filter(c=>courseIds(s,actor).includes(c.id)).map(c=>[c.id,c.title.fr]),'','required'),true)}${field('Titre',input('title','','text','required maxlength="180"'),true)}${field('Consigne',textarea('body','',5,'required minlength="10" maxlength="5000"'),true)}${field('Critères · total sur 20',input('rubric','Méthode 8 pts · résultat 8 pts · justification 4 pts','text','required maxlength="500"'),true)}${field('Échéance · heure d’Algérie',input('due','','datetime-local','required'),true)}</div>${saveButton('Créer le devoir')}</form>`;}
export function assignmentDialog(s,actor,id){const a=s.assignments.find(a=>a.id===id),sub=s.submissions.find(x=>x.assignmentId===id&&x.userId===actor.id);return `${dialogHeading(a.title,courseName(s,a.courseId))}<div class="school-lesson-objective"><p>${esc(a.body)}</p><span>${esc(a.rubric)}</span></div><p class="school-caption">À rendre le ${dateLabel(a.due,true)}. Les devoirs rendus après l’échéance restent acceptés et sont signalés comme tardifs.</p><form data-school-form="assignment-submit" data-id="${id}" class="school-form">${field('Votre démarche et votre réponse',textarea('text',sub?.text||'',8,'required minlength="10" maxlength="8000"'))}${sub?`<div class="school-feedback"><h3>${sub.grade===null?'Copie reçue, en attente de correction':`${sub.grade}/20`}</h3><p>${esc(sub.feedback||'Le professeur n’a pas encore corrigé cette version.')}</p></div><p class="school-caption">Rendre une nouvelle version remet la copie en attente de correction.</p>`:''}${saveButton(sub?'Remettre une nouvelle version':'Rendre mon devoir démo')}</form>`;}
export function submissionDialog(s,id,edit=false){const sub=s.submissions.find(x=>x.id===id),a=s.assignments.find(a=>a.id===sub.assignmentId);return `${dialogHeading(a.title,name(s,sub.userId))}<div class="school-rubric">${esc(a.rubric)}</div><div class="school-submission-text">${esc(sub.text).replace(/\n/g,'<br>')}</div><p class="school-caption">Rendu le ${dateLabel(sub.submittedAt,true)}${Date.parse(sub.submittedAt)>Date.parse(a.due)?' · après l’échéance':''}</p>${edit?`<form data-school-form="submission-grade" data-id="${id}" class="school-form"><div class="school-fields">${field('Note / 20',input('grade',sub.grade??'','number','required min="0" max="20" step="0.5"'))}${field('Retour pédagogique et prochaine étape',textarea('feedback',sub.feedback,5,'required minlength="4" maxlength="3000"'),true)}</div>${saveButton('Enregistrer la correction')}</form>`:`<div class="school-feedback"><h3>${sub.grade===null?'Correction en attente':`${sub.grade}/20`}</h3><p>${esc(sub.feedback||'Le professeur n’a pas encore corrigé ce devoir.')}</p></div>`}`;}
export function lessonDialog(s,actor,id,module=0,result=null){
 const c=findCourse(s,id),m=c.modules[module],en=s.enrollments.find(e=>e.userId===actor.id&&e.courseId===id),sample=previews[{ 'math-2as':'math','math-bac':'math','bac-sprint':'math','physics-bac':'physics','stats-r':'stats','web-ai':'web','ai-work':'ai-work'}[c.source]||c.source],bank=quizForCourse(c);
 return `${dialogHeading(c.title.fr)}<div class="school-lesson-layout"><nav aria-label="Modules de la formation" class="school-lesson-nav">${c.modules.map((item,i)=>`<button data-school-action="lesson-select" data-id="${id}" data-module="${i}" ${module===i?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(item.title)}</strong>${en?.completed.includes(i)?icon('check'):''}</button>`).join('')}</nav><section class="school-lesson-content"><span class="school-badge purple">MODULE ${module+1} / ${c.modules.length}</span><h3>${esc(m.title)}</h3><div class="school-lesson-objective"><span>OBJECTIF DU MODULE</span><p>${esc(m.text)}</p></div><p class="school-caption">Leçon de démonstration : objectifs et exercice témoin. Ce quiz reprend les bases du parcours ; il ne certifie pas la maîtrise de chaque module. Les contenus complets seront ajoutés par l’équipe.</p>${sample?`<details class="school-sample"><summary>Essayer un extrait réel du parcours</summary><p>${esc(copy(sample.task))}</p><pre dir="ltr"><code>${esc(sample.code)}</code></pre><p>${esc(copy(sample.solution))}</p><a class="school-button secondary" href="samples/${sample.file}" download>Télécharger l’extrait</a></details>`:''}${en?`<form data-school-form="lesson-complete" data-id="${id}" data-module="${module}" class="school-form"><h4>Le contrôle de compréhension</h4>${bank.map(([question,answers],i)=>`<fieldset class="school-quiz-question"><legend>${i+1}. ${esc(question)}</legend>${answers.map((answer,j)=>`<label class="school-quiz-answer"><input type="radio" name="q${i}" value="${j}" required ${result?.answers[i]===j?'checked':''}>${esc(answer)}</label>`).join('')}${result?`<p class="school-quiz-explanation ${result.answers[i]===bank[i][2]?'correct':'incorrect'}">${result.answers[i]===bank[i][2]?'✓':'↗'} ${esc(bank[i][3])}</p>`:''}</fieldset>`).join('')}${result?`<p class="school-quiz-result" role="status">${result.score}/3 · ${result.score>=2?'Module parcouru en démonstration.':'Relisez les explications, puis réessayez.'}</p>`:''}${saveButton(en.completed.includes(module)?'Revoir mon contrôle':'Vérifier et marquer le module parcouru')}</form>`:'<div class="school-coach-note">Aperçu enseignant : aucune progression d’élève n’est modifiée ici.</div>'}</section></div>`;
}
export function groupDialog(s,id){const c=findCourse(s,id),en=s.enrollments.filter(e=>e.courseId===id);return `${dialogHeading(c.title.fr,'Apprenants inscrits dans ce groupe de démonstration.')}<div class="school-group-list">${en.map(e=>`<article><div>${enrollmentRow(s,e,true)}</div>${button('Télécharger le bulletin','report-user',e.userId)}</article>`).join('')||empty('Aucun apprenant','L’administration peut attribuer ce parcours à un compte test.')}</div>`;}
export function attendanceDialog(s,id){const session=s.sessions.find(x=>x.id===id);return `${dialogHeading(session.title,dateLabel(session.start,true))}<form data-school-form="attendance-save" data-id="${id}" class="school-form">${s.enrollments.filter(e=>e.courseId===session.courseId).map(e=>field(esc(name(s,e.userId)),select(`att-${e.userId}`,Object.entries(labels),s.attendance.find(a=>a.sessionId===id&&a.userId===e.userId)?.status||'present'))).join('')}${saveButton('Enregistrer les présences')}</form>`;}
export function sessionForm(s,actor){return `${dialogHeading('Planifier une séance','Le planning vérifie les chevauchements pour le professeur attribué.')}<form data-school-form="session-save" class="school-form"><div class="school-fields">${field('Formation',select('courseId',s.courses.filter(c=>courseIds(s,actor).includes(c.id)).map(c=>[c.id,c.title.fr]),'','required'),true)}${field('Titre',input('title','','text','required maxlength="180"'),true)}${field('Début · heure d’Algérie',input('start','','datetime-local','required'))}${field('Durée en minutes',input('duration',90,'number','required min="15" max="240" step="1"'))}${field('Lien Google Meet existant (facultatif)',input('meet','','url','placeholder="https://meet.google.com/xxx-xxxx-xxx" maxlength="100"'),true)}</div><p class="school-caption">Laissez le lien vide pour une séance démo. Cette page ne crée ni réunion Meet ni invitation réelle.</p>${saveButton('Ajouter la séance')}</form>`;}
export function sessionDialog(s,actor,id){const x=s.sessions.find(x=>x.id===id),edit=['admin','teacher'].includes(actor.role);return `${dialogHeading(x.title,courseName(s,x.courseId))}<div class="school-session-detail"><strong>${dateLabel(x.start,true)}</strong><span>${x.duration} minutes · heure d’Algérie</span><p>Professeur attribué : ${esc(name(s,findCourse(s,x.courseId).teacherId))}</p></div><div class="school-lesson-objective"><span>AVANT LA SÉANCE</span><p>Préparez votre dernière tentative, vos questions et le support du cours. Une question précise fait gagner du temps à tout le groupe.</p></div><div class="school-row-actions">${x.meet?`<a class="school-button primary" href="${esc(x.meet)}" target="_blank" rel="noopener noreferrer">Ouvrir le lien Meet ↗</a>`:badge('Séance de démonstration · pas de visioconférence','purple')}${button('Télécharger .ics','session-export',id)}${edit?button('Supprimer la séance démo','session-delete',id):''}</div>`;}
export function invoiceForm(s){return `${dialogHeading('Créer une échéance fictive','Aucune facture légale ni demande de paiement réelle n’est émise.')}<form data-school-form="invoice-save" class="school-form"><div class="school-fields">${field('Apprenant',select('userId',s.users.filter(u=>LEARNERS.includes(u.role)).map(u=>[u.id,u.name]),'','required'),true)}${field('Formation',select('courseId',s.courses.map(c=>[c.id,c.title.fr]),'','required'),true)}${field('Montant en DA',input('amount','','number','required min="1" max="10000000"'))}${field('Échéance · heure d’Algérie',input('due','','datetime-local','required'))}</div>${saveButton('Créer l’échéance démo')}</form>`;}
export function invoicePayDialog(s,id){const x=s.invoices.find(x=>x.id===id);return `${dialogHeading('Simuler un règlement',`${courseName(s,x.courseId)} · ${money(x.amount)}`)}<form data-school-form="invoice-pay" data-id="${id}" class="school-form"><fieldset class="school-payment-options"><legend>Mode de règlement fictif</legend><label><input type="radio" name="method" value="edahabia" checked> Edahabia · carte de démonstration</label><label><input type="radio" name="method" value="cash"> Espèces · encaissement fictif</label></fieldset><div class="school-fake-card" aria-hidden="true"><span>NUMERIA / DEMO</span><strong>•••• •••• •••• 0000</strong><small>Aucune donnée de carte demandée</small></div><label class="school-checkbox"><input name="confirm" type="checkbox" required> Je comprends qu’aucun paiement réel n’est effectué.</label>${saveButton('Marquer payée en démonstration')}</form>`;}
export function announcementForm(){return `${dialogHeading('Une annonce pour l’école.')}<form data-school-form="announcement-save" class="school-form">${field('Titre',input('title','','text','required maxlength="180"'))}${field('Message',textarea('text','',5,'required maxlength="1600"'))}${saveButton('Publier dans cet espace démo')}</form>`;}
export function resetDialog(){return `${dialogHeading('Repartir avec les exemples initiaux.','Tous les comptes ajoutés, PDF, progrès et modifications de vitrine de cet appareil seront supprimés. Le site GitHub reste intact.')}<form data-school-form="reset" class="school-form"><label class="school-checkbox"><input name="confirm" type="checkbox" required> Réinitialiser entièrement l’espace école local.</label>${saveButton('Réinitialiser les données démo')}</form>`;}

export function reportHTML(s,id){const u=s.users.find(u=>u.id===id),m=metrics(s,u),en=s.enrollments.filter(e=>e.userId===id),subs=s.submissions.filter(x=>x.userId===id&&x.grade!==null);return `<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Numeria · bulletin de démonstration</title><style>body{font:16px/1.7 system-ui;max-width:850px;margin:40px auto;padding:24px;color:#242326}h1{font-size:38px}h2{margin-top:35px}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-bottom:1px solid #ddd}.note{background:#eee8fc;padding:18px}p{white-space:pre-wrap}@media print{body{margin:0}section{break-inside:avoid}}</style><h1>NUMERIA</h1><p class="note">Bulletin de démonstration · données fictives · ni attestation ni diplôme</p><h2>${esc(u.name)}</h2><p>Établi le ${dateLabel(new Date().toISOString())}. Moyenne : ${m.grade===null?'non disponible':m.grade.toFixed(1)+'/20'}. Présence renseignée : ${m.attendance===null?'non disponible':m.attendance+'%'}.</p><h2>Parcours</h2><table><tr><th>Formation</th><th>Modules parcourus en démo</th></tr>${en.map(e=>`<tr><td>${esc(courseName(s,e.courseId))}</td><td>${e.completed.length} / ${findCourse(s,e.courseId).modules.length} (${progress(s,e)}%)</td></tr>`).join('')}</table><h2>Devoirs et retours</h2>${subs.map(x=>`<section><h3>${esc(s.assignments.find(a=>a.id===x.assignmentId)?.title)} · ${x.grade}/20</h3><p>${esc(x.feedback)}</p></section>`).join('')||'<p>Aucun devoir noté.</p>'}<p>Ce document reprend uniquement les informations de la démonstration locale.</p></html>`;}
export function invoiceReceiptHTML(s,id){const i=s.invoices.find(x=>x.id===id);return `<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Numeria · récapitulatif fictif</title><style>body{font:17px/1.8 system-ui;max-width:720px;margin:50px auto;padding:25px;color:#242326}strong{color:#6840d8}</style><h1>NUMERIA · DÉMONSTRATION</h1><p>Récapitulatif fictif. Aucun paiement réel. Ce document n’est ni une facture ni un justificatif de paiement.</p><p>${esc(i.reference)}<br>${esc(name(s,i.userId))}<br>${esc(courseName(s,i.courseId))}</p><h2>${money(i.amount)}</h2><p>Statut : ${i.status==='paid'?'payée en démo':'en attente en démo'}<br>${i.paidAt?dateLabel(i.paidAt,true):''} · ${i.method==='cash'?'espèces':i.method==='edahabia'?'Edahabia':''}</p></html>`;}
